DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>43 OR (SELECT count(DISTINCT code) FROM _u)<>43
 OR (SELECT sum(jsonb_array_length(placements)) FROM _u)<>65 OR (SELECT count(*) FROM _p)<>28 OR (SELECT count(*) FROM _pl)<>28
 OR (SELECT sum(u.ects) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e
     WHERE e->>'role'='mandatory' AND e->>'specialization' IN ('Tronco Comum','Arqueologia')))<>140
 OR (SELECT sum(u.ects) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e
     WHERE e->>'role'='mandatory' AND e->>'specialization' IN ('Tronco Comum','Património Cultural')))<>140
 OR (SELECT count(DISTINCT e->>'group') FROM _u u, jsonb_array_elements(u.placements) e
     WHERE e->>'role'='alternative' AND e->>'specialization' IN ('Tronco Comum','Arqueologia'))<>8
 OR (SELECT count(DISTINCT e->>'group') FROM _u u, jsonb_array_elements(u.placements) e
     WHERE e->>'role'='alternative' AND e->>'specialization' IN ('Tronco Comum','Património Cultural'))<>8
 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN ('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Património Cultural e Arqueologia manifest counts or branch ECTS (each branch: 140 mandatory + 8 option groups of 5)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LPCA' OR slug='patrimonio-cultural-arqueologia'
 OR (external_source='ualg_official' AND external_id='1685')) AND id<>md5('facodi:ualg:1685:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LPCA, the slug or UAlg 1685; reconcile manually'; END IF;
END $pre$;

