INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1685:course:record')::uuid,md5('facodi:ualg:1685:course')::uuid,'LPCA','ualg_official','1685','patrimonio-cultural-arqueologia',
 'Licenciatura em Património Cultural e Arqueologia','Património Cultural e Arqueologia','Licenciatura da Faculdade de Ciências Humanas e Sociais da Universidade do Algarve, com 180 ECTS em três anos: dois anos comuns de arqueologia, história e história da arte, e dois ramos no 3.º ano, Arqueologia e Património Cultural.','<h2>Apresentação</h2><p>Licenciatura em Património Cultural e Arqueologia da Faculdade de Ciências Humanas e Sociais da Universidade do Algarve, com 180 ECTS em seis semestres. Assenta em três áreas científicas, Arqueologia, História e História da Arte, e forma para o estudo, a salvaguarda e a valorização do património arqueológico, histórico e artístico.</p><h2>Plano de estudos</h2><p>O 1.º e o 2.º anos são comuns: introdução à arqueologia, ao património cultural e à história da arte, pré-história e proto-história, arqueologia romana, medieval e urbana, história da arte e da cultura da Antiguidade à Idade Moderna, museologia e intervenção no património construído, com quatro grupos de opção no 2.º ano. No 3.º ano o curso divide-se em dois ramos: <strong>Arqueologia</strong> (técnicas de análise laboratorial de cerâmicas, faunas e líticos, e arqueociências) e <strong>Património Cultural</strong> (história da arte portuguesa e contemporânea, história da cultura portuguesa e representação gráfica do património construído). Os dois ramos partilham história da cultura contemporânea, pensamento historiográfico e arqueológico, gestão do património cultural e história do urbanismo, e cada um tem quatro grupos de opção e um seminário de investigação.</p><h2>Na FACODI</h2><p>Cada unidade curricular tem playlists abertas do YouTube escolhidas a partir do programa da ficha oficial da UC.</p>',
 'Licenciatura','pt','Faculdade de Ciências Humanas e Sociais','https://www.ualg.pt/curso/1685','https://www.ualg.pt/curso/1685/plano','active',true,
 jsonb_build_object('official_course_id','1685','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1685/plano',
 'official_program_verified',true,'official_ects_total',180,'official_unit_count',43,'branches',jsonb_build_array('Arqueologia','Património Cultural'),
 'curriculum_contains_elective_alternatives',true,'alternative_pathways_not_additive',true,
 'thematic_area','Artes, Comunicação e Património','teaching_language','Português',
 'official_plan_note','Seminários de Investigação (10 ECTS, anuais) listados no grupo OPÇÃO 6 de cada ramo; mantidos como no plano, fora da soma de 180 ECTS.',
 'source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1685_patrimonio_cultural_arqueologia_20261118'),
 'Universidade do Algarve',180,6)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
SELECT md5('facodi:ualg:1685:uc:'||u.code)::uuid,'curricular_unit',u.title,'facodi-uc-patrimonio-cultural-arqueologia-'||u.code,u.summary,'[]'::jsonb,
 u.topics,ARRAY[u.title],'pt','active',true,'import','https://www.ualg.pt/curso/1685/plano','ualg:1685:uc:'||u.code,
 jsonb_build_object('university_course_code','1685','unit_code',u.code,'official_academic_year','2026/27',
 'official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,'study_topics',to_jsonb(u.topics),'curation_batch','facodi_ualg_1685_patrimonio_cultural_arqueologia_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

-- A UC code that is already the slug of a unit in another course gets the prefix patrimonio-arqueologia-uc-; otherwise the slug is the code.
INSERT INTO facodi.curricular_units(id,learning_object_id,course_id,code,external_source,external_id,slug,title,normalized_title,summary,
 description_html,year,semester,ects,position,language,source_url,plan_url,status,published,metadata)
SELECT md5('facodi:ualg:1685:uc:record:'||u.code)::uuid,md5('facodi:ualg:1685:uc:'||u.code)::uuid,md5('facodi:ualg:1685:course:record')::uuid,
 u.code,'ualg_official','1685:'||u.code,
 CASE WHEN EXISTS(SELECT 1 FROM facodi.curricular_units o WHERE o.slug=u.code AND o.course_id<>md5('facodi:ualg:1685:course:record')::uuid)
 THEN 'patrimonio-arqueologia-uc-'||u.code ELSE u.code END,
 u.title,u.title,u.summary,'<p>'||u.summary||'</p><p><strong>Temas:</strong> '||array_to_string(u.topics,'; ')||'.</p>',
 u.year,u.semester,u.ects,u.position,'pt','https://www.ualg.pt/curso/1685/plano','https://www.ualg.pt/curso/1685/plano','active',true,
 jsonb_build_object('course_code','LPCA','official_course_id','1685','official_unit_code',u.code,'academic_year','2026/27',
 'official_plan_url','https://www.ualg.pt/curso/1685/plano','official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,
 'official_code_checked',true,'official_ects_checked',true,'official_semester_checked',true,
 'offered_in_both_semesters',u.offered_both_terms,'is_annual',u.semester IS NULL,'official_plan_note',u.plan_note,
 'is_elective_option',u.elective_only,'official_option_group',u.option_group,
 'curriculum_placements',u.placements,'study_topics',to_jsonb(u.topics),'source_quality','ualg_official_structure',
 'curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1685_patrimonio_cultural_arqueologia_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1685:course-uc-link:'||u.code)::uuid,md5('facodi:ualg:1685:course')::uuid,md5('facodi:ualg:1685:uc:'||u.code)::uuid,
 'contains',u.position,'structured_catalog_import',
 jsonb_build_object('relation_origin','ualg_1685_official_2026_27_plan','official_code',u.code,'official_ects',u.ects,'curation_batch','facodi_ualg_1685_patrimonio_cultural_arqueologia_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

